#!/usr/bin/env python3
"""Copy upstream notices without extracting/building complete source archives."""
import argparse
import hashlib
import json
from pathlib import Path, PurePosixPath
import posixpath
import re
import tarfile

NOTICE = re.compile(r"(^|[._-])(licen[sc]e|copying|copyright|notice|authors)([._-]|$)", re.I)
SPECIAL = {"qt_attribution.json", "README.chromium", "REUSE.toml", "dep5"}


def digest(path):
    result = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            result.update(block)
    return result.hexdigest()


def safe_name(name):
    name = posixpath.normpath(name)
    if name.startswith("/") or name == ".." or name.startswith("../"):
        raise ValueError("Unsafe upstream notice path")
    return name


def notice_path(name):
    path = PurePosixPath(name)
    return (bool(NOTICE.search(path.name)) or path.name in SPECIAL
            or any(part.lower() in {"licenses", "licences", "copyrights"} for part in path.parts))


def references(name, data):
    """Honor Qt's explicit license filenames, including uncommon filenames."""
    if PurePosixPath(name).name != "qt_attribution.json":
        return []
    entries = json.loads(data, strict=False)
    if isinstance(entries, dict):
        entries = [entries]
    found = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        example_only = bool(entry.get("QtParts")) and set(entry["QtParts"]) <= {"examples", "tests", "tools"}
        for field in ("LicenseFile", "LicenseFiles"):
            values = entry.get(field, [])
            values = [values] if isinstance(values, str) else values
            for value in values or []:
                if value:
                    found.append((safe_name(posixpath.join(posixpath.dirname(name), value)), example_only))
    return found


def collect_archive(archive, destination):
    written, wanted, links = {}, {}, {}

    def copy(member, stream):
        name = safe_name(member.name)
        data = stream.read()
        target = destination / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
        written[name] = hashlib.sha256(data).hexdigest()
        for reference, example_only in references(name, data):
            wanted[reference] = wanted.get(reference, True) and example_only

    # Streaming mode keeps the ~1 GiB Qt archive compressed on disk. No extractall.
    with tarfile.open(archive, mode="r|*") as source:
        for member in source:
            if member.issym() or member.islnk():
                target = member.linkname if member.islnk() else posixpath.join(posixpath.dirname(member.name), member.linkname)
                try:
                    links[safe_name(member.name)] = safe_name(target)
                except ValueError:
                    # An unrelated test symlink may point outside its source tree.
                    continue
                if notice_path(member.name):
                    wanted[safe_name(member.name)] = False
            elif member.isfile() and notice_path(member.name):
                copy(member, source.extractfile(member))
    pending = set(wanted) - set(written)
    aliases = {name: links[name] for name in pending if name in links}
    pending |= set(aliases.values())
    if pending:
        with tarfile.open(archive, mode="r|*") as source:
            for member in source:
                if member.isfile() and safe_name(member.name) in pending:
                    copy(member, source.extractfile(member))
        for name, target in aliases.items():
            if target in written:
                data = (destination / target).read_bytes()
                output = destination / name
                output.parent.mkdir(parents=True, exist_ok=True)
                output.write_bytes(data)
                written[name] = hashlib.sha256(data).hexdigest()
    unresolved = sorted(name for name in wanted if name not in written)
    required_missing = [name for name in unresolved if not wanted[name]]
    if not written:
        raise RuntimeError(f"No upstream notices found: {archive.name}")
    return {"files": written, "unresolved_references": unresolved,
            "required_missing": required_missing}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--prefix", type=Path, required=True)
    parser.add_argument("--records", type=Path, default=Path("notice-sources.json"))
    args = parser.parse_args()
    records = json.loads(args.records.read_text())
    args.prefix.mkdir(parents=True, exist_ok=True)
    report = {"scope": "Upstream source notices (superset), not a linked-code SBOM. Other wheel notices remain in their dist-info/licenses. Source URLs and SHA256 checksums are retained for review/retrieval.", "sources": []}
    failed = []
    for record in records:
        archive = Path("notice-sources") / record["filename"]
        if digest(archive) != record["sha256"]:
            raise RuntimeError(f"Notice source checksum mismatch: {record['id']}")
        destination = args.prefix / record["id"]
        if record.get("kind") == "license-file":
            destination.mkdir(parents=True, exist_ok=True)
            data = archive.read_bytes()
            (destination / "LICENSE").write_bytes(data)
            collected = {"files": {"LICENSE": hashlib.sha256(data).hexdigest()}, "unresolved_references": [], "required_missing": []}
        else:
            collected = collect_archive(archive, destination)
        report["sources"].append({**record, **collected})
        failed.extend(f"{record['id']}/{name}" for name in collected["required_missing"])
        print(f"{record['id']}: {len(collected['files'])} notice files", flush=True)
    (args.prefix / "SOURCES.json").write_text(json.dumps(report, indent=2) + "\n")
    (args.prefix / "README.txt").write_text("PhimThaiMaiPen preview includes dynamically linked Qt/PySide 6.11.1.\nPySide/Shiboken are available under LGPL-3.0-only or their stated alternatives. Each bundled Qt module and third-party component retains the license in its own notices.\nThe Qt wheel also includes ICU 73.2 and FFmpeg 7.1.3; the latter's notices are in qtmultimedia/src/3rdparty/ffmpeg within the Qt source notice tree.\nThe app's Qt Multimedia patch and build instructions are available in the same versioned GitHub source release.\nSOURCES.json records original source URLs, exact checksums and copied notice paths.\nThis is a source-notice superset; unused source components may appear.\n")
    if failed:
        raise RuntimeError("Unresolved upstream runtime license references: " + ", ".join(failed[:20]))


if __name__ == "__main__":
    main()
